package com.fasterxml.jackson.databind.node;

import com.fasterxml.jackson.annotation.JsonAutoDetect;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.jsontype.TypeSerializer;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class ObjectNode_equals_TriageGen1Test {

    private ObjectMapper mapper;
    private JsonNodeFactory factory;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        factory = mapper.getFactory();
    }

    @Test
    public void testEquals_Reflexive() {
        ObjectNode node = factory.objectNode();
        node.put("key", "value");
        // if (o == this) return true;
        assertTrue("Should be equal to itself", node.equals(node));
    }

    @Test
    public void testEquals_Null() {
        ObjectNode node = factory.objectNode();
        // if (o == null) return false;
        assertFalse("Should not be equal to null", node.equals(null));
    }

    @Test
    public void testEquals_DifferentType() {
        ObjectNode node = factory.objectNode();
        ArrayNode arrayNode = factory.arrayNode();
        // if (o instanceof ObjectNode) ... else return false;
        assertFalse("Should not be equal to a different JsonNode type", node.equals(arrayNode));
        assertFalse("Should not be equal to a String", node.equals("not a node"));
    }

    @Test
    public void testEquals_SameContent() {
        ObjectNode node1 = factory.objectNode();
        node1.put("a", 1);
        node1.put("b", "test");

        ObjectNode node2 = factory.objectNode();
        node2.put("a", 1);
        node2.put("b", "test");

        // _childrenEqual check
        assertTrue("Nodes with same content should be equal", node1.equals(node2));
    }

    @Test
    public void testEquals_DifferentContent() {
        ObjectNode node1 = factory.objectNode();
        node1.put("a", 1);

        ObjectNode node2 = factory.objectNode();
        node2.put("a", 2);

        assertFalse("Nodes with different content should not be equal", node1.equals(node2));
    }

    @Test
    public void testEquals_DifferentKeys() {
        ObjectNode node1 = factory.objectNode();
        node1.put("a", 1);

        ObjectNode node2 = factory.objectNode();
        node2.put("b", 1);

        assertFalse("Nodes with different keys should not be equal", node1.equals(node2));
    }

    @Test
    public void testEquals_NestedObjectsEqual() {
        ObjectNode node1 = factory.objectNode();
        ObjectNode inner1 = factory.objectNode();
        inner1.put("inner", "value");
        node1.set<JsonNode>("child", inner1);

        ObjectNode node2 = factory.objectNode();
        ObjectNode inner2 = factory.objectNode();
        inner2.put("inner", "value");
        node2.set<JsonNode>("child", inner2);

        assertTrue("Nested objects should be compared for equality", node1.equals(node2));
    }

    @Test
    public void testEquals_NestedObjectsNotEqual() {
        ObjectNode node1 = factory.objectNode();
        ObjectNode inner1 = factory.objectNode();
        inner1.put("inner", "value1");
        node1.set<JsonNode>("child", inner1);

        ObjectNode node2 = factory.objectNode();
        ObjectNode inner2 = factory.objectNode();
        inner2.put("inner", "value2");
        node2.set<JsonNode>("child", inner2);

        assertFalse("Nested objects with different values should fail equality", node1.equals(node2));
    }

    @Test
    public void testEquals_EmptyNodes() {
        ObjectNode node1 = factory.objectNode();
        ObjectNode node2 = factory.objectNode();
        assertTrue("Two empty ObjectNodes should be equal", node1.equals(node2));
    }
}
